sys_script.script:
var nm = new GlideRecord('sys_number');
nm.addQuery('category.name', 'x_2182380_pwcnow_employee_document');
nm.query();
if (nm.next()) {
    var nextNum = parseInt(nm.getValue('number'), 10) + 1;
    nm.setValue('number', nextNum);
    nm.update();
    var prefix = nm.getValue('prefix');
    var maxDigits = parseInt(nm.getValue('maximum_digits'), 10);
    var padded = String(nextNum);
    while (padded.length < maxDigits) {
        padded = '0' + padded;
    }
    current.setValue('number', prefix + padded);
}
